/* LearnForge Global Styles */
:root {
  --black: #000000;
  --lime: #E6FF32;
  --burgundy: #7F2A23;
  --white: #ffffff;
  --gray-50: #f9fafb;
  --gray-100: #f3f4f6;
  --gray-200: #e5e7eb;
  --gray-400: #9ca3af;
  --gray-600: #4b5563;
  --gray-700: #374151;
  --gray-900: #111827;
  --font-heading: 'Plus Jakarta Sans', 'Inter', sans-serif;
  --font-body: 'Inter', sans-serif;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 16px rgba(0,0,0,.10);
  --shadow-lg: 0 12px 40px rgba(0,0,0,.12);
  --transition: .22s cubic-bezier(.4,0,.2,1);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
a { text-decoration: none; color: inherit; }

/* ─── Typography ─── */
h1, h2, h3, h4, h5 {
  font-family: var(--font-heading);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.02em;
}
h1 { font-size: clamp(2.4rem, 5vw, 4rem); }
h2 { font-size: clamp(1.8rem, 3.5vw, 2.8rem); }
h3 { font-size: clamp(1.3rem, 2.5vw, 1.8rem); }
h4 { font-size: 1.15rem; font-weight: 700; }
p  { color: var(--gray-600); line-height: 1.7; }

/* ─── Layout ─── */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}
.section { padding: 96px 0; }
.section-sm { padding: 64px 0; }

/* ─── Buttons ─── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: .95rem;
  padding: 14px 28px;
  border-radius: 50px;
  cursor: pointer;
  transition: var(--transition);
  border: 2px solid transparent;
  white-space: nowrap;
}
.btn-primary {
  background: var(--black);
  color: var(--lime);
  border-color: var(--black);
}
.btn-primary:hover {
  background: var(--gray-900);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0,0,0,.25);
}
.btn-outline {
  background: transparent;
  color: var(--black);
  border-color: var(--black);
}
.btn-outline:hover {
  background: var(--black);
  color: var(--lime);
  transform: translateY(-2px);
}
.btn-lime {
  background: var(--lime);
  color: var(--black);
  border-color: var(--lime);
}
.btn-lime:hover {
  background: #d4eb1a;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(230,255,50,.35);
}
.btn-sm { padding: 10px 20px; font-size: .875rem; }

/* ─── Nav ─── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}
.nav.scrolled { box-shadow: var(--shadow-md); }
.nav-inner {
  display: flex;
  align-items: center;
  gap: 32px;
  height: 68px;
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 900;
  color: var(--black);
  letter-spacing: -0.04em;
  margin-right: auto;
  display: flex;
  align-items: center;
  gap: 6px;
}
.nav-logo span {
  display: inline-block;
  width: 28px;
  height: 28px;
  background: var(--lime);
  border-radius: 6px;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
}
.nav-links a {
  font-size: .9rem;
  font-weight: 600;
  color: var(--gray-700);
  padding: 8px 14px;
  border-radius: 8px;
  transition: var(--transition);
}
.nav-links a:hover, .nav-links a.active {
  color: var(--black);
  background: var(--gray-100);
}
.nav-cta { margin-left: 8px; }

/* Mobile nav toggle */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 4px;
  background: none;
  border: none;
}
.nav-toggle span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--black);
  border-radius: 2px;
  transition: var(--transition);
}

/* ─── Hero ─── */
.hero {
  background: var(--black);
  color: var(--white);
  padding: 80px 0 0;
  overflow: hidden;
  position: relative;
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 80% 60% at 70% 50%, rgba(230,255,50,.12) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content { position: relative; z-index: 1; text-align: center; max-width: 800px; margin: 0 auto 56px; }
.hero h1 { color: var(--white); margin-bottom: 20px; }
.hero h1 em { color: var(--lime); font-style: normal; }
.hero p { color: rgba(255,255,255,.72); font-size: 1.15rem; max-width: 600px; margin: 0 auto 36px; }
.hero-actions { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }

/* Tab switcher */
.hero-tabs {
  display: inline-flex;
  background: rgba(255,255,255,.1);
  border-radius: 50px;
  padding: 4px;
  gap: 0;
  margin-bottom: 48px;
}
.hero-tab {
  padding: 10px 24px;
  border-radius: 50px;
  font-size: .9rem;
  font-weight: 700;
  cursor: pointer;
  color: rgba(255,255,255,.6);
  transition: var(--transition);
  border: none;
  background: transparent;
  font-family: var(--font-heading);
}
.hero-tab.active {
  background: var(--lime);
  color: var(--black);
}
.hero-preview {
  display: none;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-xl) var(--radius-xl) 0 0;
  overflow: hidden;
  max-width: 900px;
  margin: 0 auto;
}
.hero-preview.active { display: block; }
.preview-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 20px;
  background: rgba(255,255,255,.08);
  border-bottom: 1px solid rgba(255,255,255,.08);
}
.preview-dot { width: 10px; height: 10px; border-radius: 50%; }
.preview-dot:nth-child(1) { background: #ff5f57; }
.preview-dot:nth-child(2) { background: #febc2e; }
.preview-dot:nth-child(3) { background: #28c840; }
.preview-url {
  flex: 1;
  background: rgba(255,255,255,.1);
  border-radius: 6px;
  padding: 5px 14px;
  font-size: .78rem;
  color: rgba(255,255,255,.5);
  margin: 0 12px;
}
.preview-screen {
  height: 360px;
  background: linear-gradient(160deg, #111 0%, #1a1a2e 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px;
  position: relative;
  overflow: hidden;
}
.preview-screen-student {
  background: linear-gradient(160deg, #0d1b2a 0%, #1b2838 100%);
}
.preview-card {
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-md);
  padding: 20px 24px;
  min-width: 180px;
  color: var(--white);
}
.preview-card h5 { font-size: .85rem; color: rgba(255,255,255,.5); font-weight: 600; margin-bottom: 6px; }
.preview-card .big-num { font-size: 2.2rem; font-weight: 800; color: var(--lime); }
.preview-card .sub { font-size: .78rem; color: rgba(255,255,255,.45); }
.preview-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; width: 100%; max-width: 700px; }
.preview-progress {
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-md);
  padding: 18px;
  color: var(--white);
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.progress-bar-bg { height: 6px; background: rgba(255,255,255,.15); border-radius: 3px; overflow: hidden; }
.progress-bar-fill { height: 100%; background: var(--lime); border-radius: 3px; }
.preview-course-list { display: flex; flex-direction: column; gap: 10px; width: 100%; max-width: 480px; }
.course-item {
  display: flex;
  align-items: center;
  gap: 14px;
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-sm);
  padding: 14px;
}
.course-thumb { width: 48px; height: 48px; border-radius: 6px; background: var(--lime); opacity: .8; flex-shrink: 0; }
.course-info { flex: 1; }
.course-info h6 { font-size: .85rem; color: var(--white); font-weight: 700; margin-bottom: 4px; }
.course-info p { font-size: .75rem; color: rgba(255,255,255,.5); margin: 0; line-height: 1.4; }

/* ─── Stats Bar ─── */
.stats-bar {
  background: var(--lime);
  padding: 36px 0;
}
.stats-bar .container {
  display: flex;
  justify-content: center;
  gap: 64px;
  flex-wrap: wrap;
}
.stat-item { text-align: center; }
.stat-num {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 900;
  color: var(--black);
  line-height: 1;
  letter-spacing: -0.03em;
}
.stat-label { font-size: .875rem; font-weight: 600; color: rgba(0,0,0,.6); margin-top: 4px; }

/* ─── Section Headers ─── */
.section-label {
  display: inline-block;
  font-size: .8rem;
  font-weight: 800;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--burgundy);
  background: rgba(127,42,35,.08);
  padding: 4px 14px;
  border-radius: 50px;
  margin-bottom: 16px;
}
.section-header { text-align: center; max-width: 680px; margin: 0 auto 64px; }
.section-header p { font-size: 1.1rem; margin-top: 14px; }

/* ─── Product Cards ─── */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}
.product-card {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  transition: var(--transition);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.product-card:hover {
  border-color: var(--black);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.product-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-sm);
  background: var(--lime);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}
.product-card h3 { font-size: 1.2rem; }
.product-card p { font-size: .95rem; }
.product-card .arrow {
  margin-top: auto;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  transition: var(--transition);
}
.product-card:hover .arrow { background: var(--black); color: var(--lime); }

/* ─── Why Choose Us Tabs ─── */
.why-tabs {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 40px;
  justify-content: center;
}
.why-tab {
  padding: 10px 20px;
  border-radius: 50px;
  font-weight: 700;
  font-size: .875rem;
  cursor: pointer;
  background: var(--gray-100);
  color: var(--gray-700);
  border: 2px solid transparent;
  transition: var(--transition);
  font-family: var(--font-heading);
}
.why-tab.active, .why-tab:hover {
  background: var(--black);
  color: var(--lime);
  border-color: var(--black);
}
.why-panel { display: none; }
.why-panel.active { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; }
.why-features { display: flex; flex-direction: column; gap: 20px; }
.why-feature {
  display: flex;
  gap: 14px;
  align-items: flex-start;
}
.why-feature-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: var(--lime);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  flex-shrink: 0;
}
.why-feature h4 { font-size: 1rem; margin-bottom: 3px; }
.why-feature p { font-size: .9rem; }
.why-visual {
  background: var(--gray-50);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-xl);
  height: 340px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
}
.why-visual-inner { text-align: center; }
.why-visual-inner .emoji { font-size: 4rem; margin-bottom: 16px; display: block; }
.why-visual-inner p { font-size: .9rem; color: var(--gray-600); }

/* ─── Feature Cards (3-col) ─── */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 28px;
}
.feature-card {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  transition: var(--transition);
}
.feature-card:hover {
  border-color: var(--gray-400);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}
.feature-card .fc-icon {
  width: 52px;
  height: 52px;
  background: var(--black);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  margin-bottom: 20px;
}
.feature-card h3 { font-size: 1.15rem; margin-bottom: 10px; }
.feature-card p { font-size: .93rem; }

/* ─── Testimonials Carousel ─── */
.testimonials-section { background: var(--black); color: var(--white); }
.testimonials-section .section-label { background: rgba(230,255,50,.15); color: var(--lime); }
.testimonials-section .section-header h2 { color: var(--white); }
.testimonials-section .section-header p { color: rgba(255,255,255,.6); }
.carousel-wrapper { position: relative; overflow: hidden; }
.carousel-track {
  display: flex;
  gap: 24px;
  transition: transform .45s cubic-bezier(.4,0,.2,1);
}
.testimonial-card {
  flex: 0 0 calc(33.333% - 16px);
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: var(--radius-lg);
  padding: 32px 28px;
}
.testimonial-tag {
  display: inline-block;
  background: var(--lime);
  color: var(--black);
  font-size: .75rem;
  font-weight: 800;
  padding: 3px 10px;
  border-radius: 50px;
  margin-bottom: 14px;
}
.testimonial-card blockquote {
  font-size: 1rem;
  color: rgba(255,255,255,.85);
  line-height: 1.7;
  margin-bottom: 20px;
  font-style: italic;
}
.testimonial-author { display: flex; align-items: center; gap: 12px; }
.author-avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: var(--burgundy);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: .9rem;
  color: var(--lime);
  flex-shrink: 0;
}
.author-name { font-weight: 700; color: var(--white); font-size: .9rem; }
.author-title { font-size: .8rem; color: rgba(255,255,255,.5); }
.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 36px;
  align-items: center;
}
.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,.2);
  background: rgba(255,255,255,.06);
  color: var(--white);
  cursor: pointer;
  font-size: 1rem;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel-btn:hover { background: var(--lime); color: var(--black); border-color: var(--lime); }
.carousel-dots { display: flex; gap: 8px; }
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,.25);
  cursor: pointer;
  transition: var(--transition);
}
.carousel-dot.active { background: var(--lime); width: 24px; border-radius: 4px; }

/* ─── Pricing Overview ─── */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 20px;
  margin-bottom: 40px;
}
.pricing-card {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  transition: var(--transition);
  position: relative;
}
.pricing-card.featured {
  border-color: var(--black);
  background: var(--black);
  color: var(--white);
}
.pricing-card.featured p { color: rgba(255,255,255,.65); }
.pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--lime);
  color: var(--black);
  font-size: .72rem;
  font-weight: 800;
  padding: 4px 12px;
  border-radius: 50px;
  white-space: nowrap;
}
.pricing-name { font-weight: 800; font-size: 1rem; margin-bottom: 8px; font-family: var(--font-heading); }
.pricing-price {
  font-family: var(--font-heading);
  font-weight: 900;
  font-size: 2.2rem;
  letter-spacing: -0.03em;
  color: var(--black);
  line-height: 1;
  margin-bottom: 4px;
}
.pricing-card.featured .pricing-price { color: var(--lime); }
.pricing-period { font-size: .8rem; color: var(--gray-400); margin-bottom: 20px; }
.pricing-card.featured .pricing-period { color: rgba(255,255,255,.5); }
.pricing-features { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.pricing-features li {
  font-size: .875rem;
  color: var(--gray-600);
  display: flex;
  align-items: flex-start;
  gap: 8px;
  line-height: 1.4;
}
.pricing-features li::before {
  content: '✓';
  font-weight: 900;
  color: var(--burgundy);
  flex-shrink: 0;
}
.pricing-card.featured .pricing-features li { color: rgba(255,255,255,.7); }
.pricing-card.featured .pricing-features li::before { color: var(--lime); }

/* ─── Integrations ─── */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: 16px;
}
.integration-item {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 20px 16px;
  text-align: center;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}
.integration-item:hover {
  border-color: var(--black);
  box-shadow: var(--shadow-sm);
  transform: translateY(-2px);
}
.integration-logo {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  font-weight: 800;
}
.integration-item span {
  font-size: .78rem;
  font-weight: 700;
  color: var(--gray-700);
}

/* ─── FAQ Accordion ─── */
.faq-list { max-width: 760px; margin: 0 auto; display: flex; flex-direction: column; gap: 12px; }
.faq-item {
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: var(--transition);
}
.faq-item.open { border-color: var(--black); }
.faq-question {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 24px;
  cursor: pointer;
  font-weight: 700;
  font-size: 1rem;
  transition: var(--transition);
  background: var(--white);
  gap: 16px;
}
.faq-question:hover { background: var(--gray-50); }
.faq-item.open .faq-question { background: var(--black); color: var(--white); }
.faq-chevron {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .8rem;
  flex-shrink: 0;
  transition: transform var(--transition);
}
.faq-item.open .faq-chevron { background: var(--lime); transform: rotate(180deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height .35s ease;
}
.faq-answer-inner { padding: 0 24px 20px; color: var(--gray-600); font-size: .95rem; line-height: 1.7; }

/* ─── Global Scale ─── */
.global-section { background: var(--gray-50); }
.global-content { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
.global-map {
  background: var(--black);
  border-radius: var(--radius-xl);
  height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.global-map-dots { font-size: 5rem; opacity: .2; position: absolute; }
.global-map-stat {
  background: var(--lime);
  border-radius: var(--radius-md);
  padding: 20px 28px;
  text-align: center;
  position: relative;
  z-index: 1;
}
.global-map-stat .num { font-size: 2.5rem; font-weight: 900; color: var(--black); font-family: var(--font-heading); letter-spacing: -0.03em; }
.global-map-stat .lbl { font-size: .85rem; font-weight: 700; color: rgba(0,0,0,.6); }

/* ─── AI Automations ─── */
.ai-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
}
.ai-card {
  background: var(--black);
  border-radius: var(--radius-lg);
  padding: 32px 26px;
  color: var(--white);
  transition: var(--transition);
  border: 1px solid rgba(255,255,255,.06);
}
.ai-card:hover { border-color: var(--lime); transform: translateY(-3px); }
.ai-card .ai-icon {
  width: 48px;
  height: 48px;
  background: var(--lime);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
  margin-bottom: 18px;
}
.ai-card h4 { color: var(--white); font-size: 1.05rem; margin-bottom: 8px; }
.ai-card p { color: rgba(255,255,255,.6); font-size: .9rem; }

/* ─── Social Proof Bar ─── */
.social-proof { background: var(--black); padding: 48px 0; }
.social-proof-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  flex-wrap: wrap;
}
.social-logos { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; }
.social-logo-pill {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 50px;
  padding: 8px 18px;
  font-size: .8rem;
  font-weight: 700;
  color: rgba(255,255,255,.6);
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ─── 3-Steps Section ─── */
.steps-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 32px; }
.step-card {
  position: relative;
  padding: 36px 28px;
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  transition: var(--transition);
}
.step-card:hover { border-color: var(--black); box-shadow: var(--shadow-md); transform: translateY(-3px); }
.step-num {
  font-family: var(--font-heading);
  font-size: 4rem;
  font-weight: 900;
  color: var(--lime);
  line-height: 1;
  margin-bottom: 16px;
  -webkit-text-stroke: 2px var(--gray-200);
  color: transparent;
  position: relative;
}
.step-num::after {
  content: attr(data-num);
  position: absolute;
  left: 0;
  top: 0;
  color: var(--lime);
  -webkit-text-stroke: 0;
}
.step-card h3 { font-size: 1.15rem; margin-bottom: 10px; }
.step-card p { font-size: .92rem; }

/* ─── Tools Grid ─── */
.tools-section { background: var(--gray-50); }
.tools-categories { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 24px; }
.tools-category {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 24px;
}
.tools-category-label {
  font-size: .75rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--burgundy);
  margin-bottom: 14px;
}
.tool-tag {
  display: inline-block;
  background: var(--gray-100);
  color: var(--gray-700);
  padding: 5px 12px;
  border-radius: 50px;
  font-size: .8rem;
  font-weight: 600;
  margin: 3px 3px 0 0;
}

/* ─── CTA Banner ─── */
.cta-banner {
  background: var(--black);
  text-align: center;
  padding: 80px 0;
  position: relative;
  overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 70% 80% at 50% 50%, rgba(230,255,50,.1) 0%, transparent 70%);
}
.cta-banner .container { position: relative; }
.cta-banner h2 { color: var(--white); margin-bottom: 16px; max-width: 640px; margin: 0 auto 16px; }
.cta-banner p { color: rgba(255,255,255,.65); margin-bottom: 36px; font-size: 1.05rem; }
.cta-actions { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }

/* ─── Resources ─── */
.resources-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 24px; }
.resource-card {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: var(--transition);
}
.resource-card:hover { border-color: var(--black); box-shadow: var(--shadow-md); transform: translateY(-3px); }
.resource-img {
  height: 140px;
  background: linear-gradient(135deg, var(--black) 0%, #1a1a2e 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  position: relative;
}
.resource-img-label {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--lime);
  color: var(--black);
  font-size: .7rem;
  font-weight: 800;
  padding: 3px 10px;
  border-radius: 50px;
}
.resource-body { padding: 24px; }
.resource-body h4 { font-size: 1rem; margin-bottom: 8px; }
.resource-body p { font-size: .88rem; }
.resource-link { display: inline-flex; align-items: center; gap: 6px; color: var(--black); font-weight: 700; font-size: .875rem; margin-top: 14px; }
.resource-link:hover { text-decoration: underline; }

/* ─── Membership Pricing ─── */
.membership-tiers { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 24px; }
.tier-card {
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  transition: var(--transition);
  background: var(--white);
  position: relative;
}
.tier-card:hover { border-color: var(--black); box-shadow: var(--shadow-md); }
.tier-card.highlight { border-color: var(--black); background: var(--black); }
.tier-card.highlight h3, .tier-card.highlight .tier-price { color: var(--white); }
.tier-card.highlight p { color: rgba(255,255,255,.55); }
.tier-name { font-size: .8rem; font-weight: 800; text-transform: uppercase; letter-spacing: .1em; color: var(--burgundy); margin-bottom: 8px; }
.tier-card.highlight .tier-name { color: var(--lime); }
.tier-price { font-family: var(--font-heading); font-size: 2.4rem; font-weight: 900; letter-spacing: -0.03em; color: var(--black); line-height: 1; }
.tier-period { font-size: .8rem; color: var(--gray-400); margin-bottom: 16px; }
.tier-card.highlight .tier-period { color: rgba(255,255,255,.4); }
.tier-features { list-style: none; display: flex; flex-direction: column; gap: 10px; margin-bottom: 28px; }
.tier-features li { font-size: .875rem; color: var(--gray-600); display: flex; gap: 8px; align-items: flex-start; }
.tier-features li::before { content: '✓'; color: var(--burgundy); font-weight: 900; flex-shrink: 0; }
.tier-card.highlight .tier-features li { color: rgba(255,255,255,.65); }
.tier-card.highlight .tier-features li::before { color: var(--lime); }

/* ─── Footer ─── */
.footer {
  background: var(--black);
  color: rgba(255,255,255,.65);
  padding: 64px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}
.footer-brand .nav-logo { margin-bottom: 14px; color: var(--white); }
.footer-brand p { font-size: .875rem; line-height: 1.7; max-width: 260px; }
.footer-col h5 {
  font-size: .875rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: .06em;
}
.footer-links { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-links a { font-size: .875rem; color: rgba(255,255,255,.55); transition: color var(--transition); }
.footer-links a:hover { color: var(--lime); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  font-size: .8rem;
}
.footer-bottom a { color: rgba(255,255,255,.45); transition: color var(--transition); }
.footer-bottom a:hover { color: var(--lime); }

/* ─── Value Prop Cards ─── */
.value-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 28px; }
.value-card {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  transition: var(--transition);
}
.value-card:hover { border-color: var(--black); box-shadow: var(--shadow-md); transform: translateY(-3px); }
.value-num {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 900;
  color: var(--lime);
  line-height: 1;
  margin-bottom: 16px;
  -webkit-text-stroke: 2px var(--gray-900);
}
.value-card h3 { font-size: 1.1rem; margin-bottom: 8px; }

/* ─── File Types Grid ─── */
.file-types-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 16px; }
.file-type-item {
  background: var(--gray-50);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 24px 16px;
  text-align: center;
  transition: var(--transition);
}
.file-type-item:hover { border-color: var(--black); background: var(--lime); }
.file-type-item:hover span { color: var(--black); }
.file-type-icon { font-size: 1.8rem; margin-bottom: 8px; }
.file-type-item span { font-size: .8rem; font-weight: 700; color: var(--gray-700); }

/* ─── Coaching Spotlight ─── */
.spotlight-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 24px; }
.spotlight-card {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: var(--transition);
}
.spotlight-card:hover { border-color: var(--black); box-shadow: var(--shadow-md); transform: translateY(-3px); }
.spotlight-header {
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  position: relative;
}
.spotlight-body { padding: 24px; }
.spotlight-body h3 { font-size: 1.1rem; margin-bottom: 8px; }
.spotlight-body p { font-size: .9rem; }

/* ─── Hero Variants ─── */
.hero-split {
  background: var(--black);
  color: var(--white);
  padding: 100px 0 80px;
  position: relative;
  overflow: hidden;
}
.hero-split::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 60% 80% at 80% 50%, rgba(230,255,50,.1) 0%, transparent 60%);
}
.hero-split .container { position: relative; z-index: 1; display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
.hero-split h1 { color: var(--white); margin-bottom: 20px; }
.hero-split p { color: rgba(255,255,255,.72); font-size: 1.1rem; margin-bottom: 36px; }
.hero-illustration {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-xl);
  height: 360px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
}
.hero-float-card {
  background: rgba(255,255,255,.1);
  border: 1px solid rgba(255,255,255,.15);
  border-radius: var(--radius-md);
  padding: 16px 20px;
  color: var(--white);
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 14px;
}
.float-icon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  background: var(--lime);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  flex-shrink: 0;
  color: var(--black);
}
.float-text h5 { font-size: .9rem; color: var(--white); }
.float-text p { font-size: .78rem; color: rgba(255,255,255,.55); margin: 0; }

/* ─── Membership Stats ─── */
.membership-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 28px; }
.membership-stat-card {
  background: var(--black);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  text-align: center;
  color: var(--white);
}
.membership-stat-num {
  font-family: var(--font-heading);
  font-size: 2.8rem;
  font-weight: 900;
  color: var(--lime);
  letter-spacing: -0.03em;
  margin-bottom: 8px;
}
.membership-stat-card h4 { color: var(--white); font-size: 1rem; margin-bottom: 10px; }
.membership-stat-card p { color: rgba(255,255,255,.55); font-size: .875rem; }

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
  .footer-brand { grid-column: span 3; }
  .hero-split .container { grid-template-columns: 1fr; }
  .hero-illustration { display: none; }
  .global-content { grid-template-columns: 1fr; }
  .why-panel.active { grid-template-columns: 1fr; }
}
@media (max-width: 768px) {
  .section { padding: 64px 0; }
  .nav-links, .nav-cta { display: none; }
  .nav-toggle { display: flex; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: 68px;
    left: 0;
    right: 0;
    background: var(--white);
    border-bottom: 1px solid var(--gray-200);
    padding: 16px 24px;
    box-shadow: var(--shadow-md);
    z-index: 99;
  }
  .nav-cta.open { display: flex; padding: 0 24px 16px; position: fixed; top: auto; bottom: 0; left: 0; right: 0; z-index: 99; background: var(--white); border-top: 1px solid var(--gray-200); box-shadow: var(--shadow-md); padding: 16px 24px; }
  .testimonial-card { flex: 0 0 calc(100% - 0px); }
  .stats-bar .container { gap: 32px; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-brand { grid-column: span 2; }
  .hero-preview { display: none !important; }
  .pricing-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-brand { grid-column: span 1; }
  .pricing-grid { grid-template-columns: 1fr; }
}

/* LearnForge Global Styles */
:root {
  --black: #000000;
  --lime: #E6FF32;
  --burgundy: #7F2A23;
  --white: #ffffff;
  --gray-50: #f9fafb;
  --gray-100: #f3f4f6;
  --gray-200: #e5e7eb;
  --gray-400: #9ca3af;
  --gray-600: #4b5563;
  --gray-700: #374151;
  --gray-900: #111827;
  --font-heading: 'Plus Jakarta Sans', 'Inter', sans-serif;
  --font-body: 'Inter', sans-serif;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 16px rgba(0,0,0,.10);
  --shadow-lg: 0 12px 40px rgba(0,0,0,.12);
  --transition: .22s cubic-bezier(.4,0,.2,1);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
a { text-decoration: none; color: inherit; }

/* ─── Typography ─── */
h1, h2, h3, h4, h5 {
  font-family: var(--font-heading);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.02em;
}
h1 { font-size: clamp(2.4rem, 5vw, 4rem); }
h2 { font-size: clamp(1.8rem, 3.5vw, 2.8rem); }
h3 { font-size: clamp(1.3rem, 2.5vw, 1.8rem); }
h4 { font-size: 1.15rem; font-weight: 700; }
p  { color: var(--gray-600); line-height: 1.7; }

/* ─── Layout ─── */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}
.section { padding: 96px 0; }
.section-sm { padding: 64px 0; }

/* ─── Buttons ─── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: .95rem;
  padding: 14px 28px;
  border-radius: 50px;
  cursor: pointer;
  transition: var(--transition);
  border: 2px solid transparent;
  white-space: nowrap;
}
.btn-primary {
  background: var(--black);
  color: var(--lime);
  border-color: var(--black);
}
.btn-primary:hover {
  background: var(--gray-900);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0,0,0,.25);
}
.btn-outline {
  background: transparent;
  color: var(--black);
  border-color: var(--black);
}
.btn-outline:hover {
  background: var(--black);
  color: var(--lime);
  transform: translateY(-2px);
}
.btn-lime {
  background: var(--lime);
  color: var(--black);
  border-color: var(--lime);
}
.btn-lime:hover {
  background: #d4eb1a;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(230,255,50,.35);
}
.btn-sm { padding: 10px 20px; font-size: .875rem; }

/* ─── Nav ─── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}
.nav.scrolled { box-shadow: var(--shadow-md); }
.nav-inner {
  display: flex;
  align-items: center;
  gap: 32px;
  height: 68px;
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 900;
  color: var(--black);
  letter-spacing: -0.04em;
  margin-right: auto;
  display: flex;
  align-items: center;
  gap: 6px;
}
.nav-logo span {
  display: inline-block;
  width: 28px;
  height: 28px;
  background: var(--lime);
  border-radius: 6px;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
}
.nav-links a {
  font-size: .9rem;
  font-weight: 600;
  color: var(--gray-700);
  padding: 8px 14px;
  border-radius: 8px;
  transition: var(--transition);
}
.nav-links a:hover, .nav-links a.active {
  color: var(--black);
  background: var(--gray-100);
}
.nav-cta { margin-left: 8px; }

/* Mobile nav toggle */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 4px;
  background: none;
  border: none;
}
.nav-toggle span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--black);
  border-radius: 2px;
  transition: var(--transition);
}

/* ─── Hero ─── */
.hero {
  background: var(--black);
  color: var(--white);
  padding: 80px 0 0;
  overflow: hidden;
  position: relative;
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 80% 60% at 70% 50%, rgba(230,255,50,.12) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content { position: relative; z-index: 1; text-align: center; max-width: 800px; margin: 0 auto 56px; }
.hero h1 { color: var(--white); margin-bottom: 20px; }
.hero h1 em { color: var(--lime); font-style: normal; }
.hero p { color: rgba(255,255,255,.72); font-size: 1.15rem; max-width: 600px; margin: 0 auto 36px; }
.hero-actions { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }

/* Tab switcher */
.hero-tabs {
  display: inline-flex;
  background: rgba(255,255,255,.1);
  border-radius: 50px;
  padding: 4px;
  gap: 0;
  margin-bottom: 48px;
}
.hero-tab {
  padding: 10px 24px;
  border-radius: 50px;
  font-size: .9rem;
  font-weight: 700;
  cursor: pointer;
  color: rgba(255,255,255,.6);
  transition: var(--transition);
  border: none;
  background: transparent;
  font-family: var(--font-heading);
}
.hero-tab.active {
  background: var(--lime);
  color: var(--black);
}
.hero-preview {
  display: none;
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-xl) var(--radius-xl) 0 0;
  overflow: hidden;
  max-width: 900px;
  margin: 0 auto;
}
.hero-preview.active { display: block; }
.preview-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 20px;
  background: rgba(255,255,255,.08);
  border-bottom: 1px solid rgba(255,255,255,.08);
}
.preview-dot { width: 10px; height: 10px; border-radius: 50%; }
.preview-dot:nth-child(1) { background: #ff5f57; }
.preview-dot:nth-child(2) { background: #febc2e; }
.preview-dot:nth-child(3) { background: #28c840; }
.preview-url {
  flex: 1;
  background: rgba(255,255,255,.1);
  border-radius: 6px;
  padding: 5px 14px;
  font-size: .78rem;
  color: rgba(255,255,255,.5);
  margin: 0 12px;
}
.preview-screen {
  height: 360px;
  background: linear-gradient(160deg, #111 0%, #1a1a2e 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px;
  position: relative;
  overflow: hidden;
}
.preview-screen-student {
  background: linear-gradient(160deg, #0d1b2a 0%, #1b2838 100%);
}
.preview-card {
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-md);
  padding: 20px 24px;
  min-width: 180px;
  color: var(--white);
}
.preview-card h5 { font-size: .85rem; color: rgba(255,255,255,.5); font-weight: 600; margin-bottom: 6px; }
.preview-card .big-num { font-size: 2.2rem; font-weight: 800; color: var(--lime); }
.preview-card .sub { font-size: .78rem; color: rgba(255,255,255,.45); }
.preview-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; width: 100%; max-width: 700px; }
.preview-progress {
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-md);
  padding: 18px;
  color: var(--white);
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.progress-bar-bg { height: 6px; background: rgba(255,255,255,.15); border-radius: 3px; overflow: hidden; }
.progress-bar-fill { height: 100%; background: var(--lime); border-radius: 3px; }
.preview-course-list { display: flex; flex-direction: column; gap: 10px; width: 100%; max-width: 480px; }
.course-item {
  display: flex;
  align-items: center;
  gap: 14px;
  background: rgba(255,255,255,.07);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-sm);
  padding: 14px;
}
.course-thumb { width: 48px; height: 48px; border-radius: 6px; background: var(--lime); opacity: .8; flex-shrink: 0; }
.course-info { flex: 1; }
.course-info h6 { font-size: .85rem; color: var(--white); font-weight: 700; margin-bottom: 4px; }
.course-info p { font-size: .75rem; color: rgba(255,255,255,.5); margin: 0; line-height: 1.4; }

/* ─── Stats Bar ─── */
.stats-bar {
  background: var(--lime);
  padding: 36px 0;
}
.stats-bar .container {
  display: flex;
  justify-content: center;
  gap: 64px;
  flex-wrap: wrap;
}
.stat-item { text-align: center; }
.stat-num {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 900;
  color: var(--black);
  line-height: 1;
  letter-spacing: -0.03em;
}
.stat-label { font-size: .875rem; font-weight: 600; color: rgba(0,0,0,.6); margin-top: 4px; }

/* ─── Section Headers ─── */
.section-label {
  display: inline-block;
  font-size: .8rem;
  font-weight: 800;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--burgundy);
  background: rgba(127,42,35,.08);
  padding: 4px 14px;
  border-radius: 50px;
  margin-bottom: 16px;
}
.section-header { text-align: center; max-width: 680px; margin: 0 auto 64px; }
.section-header p { font-size: 1.1rem; margin-top: 14px; }

/* ─── Product Cards ─── */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}
.product-card {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  transition: var(--transition);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.product-card:hover {
  border-color: var(--black);
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.product-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-sm);
  background: var(--lime);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}
.product-card h3 { font-size: 1.2rem; }
.product-card p { font-size: .95rem; }
.product-card .arrow {
  margin-top: auto;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  transition: var(--transition);
}
.product-card:hover .arrow { background: var(--black); color: var(--lime); }

/* ─── Why Choose Us Tabs ─── */
.why-tabs {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 40px;
  justify-content: center;
}
.why-tab {
  padding: 10px 20px;
  border-radius: 50px;
  font-weight: 700;
  font-size: .875rem;
  cursor: pointer;
  background: var(--gray-100);
  color: var(--gray-700);
  border: 2px solid transparent;
  transition: var(--transition);
  font-family: var(--font-heading);
}
.why-tab.active, .why-tab:hover {
  background: var(--black);
  color: var(--lime);
  border-color: var(--black);
}
.why-panel { display: none; }
.why-panel.active { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center; }
.why-features { display: flex; flex-direction: column; gap: 20px; }
.why-feature {
  display: flex;
  gap: 14px;
  align-items: flex-start;
}
.why-feature-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: var(--lime);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  flex-shrink: 0;
}
.why-feature h4 { font-size: 1rem; margin-bottom: 3px; }
.why-feature p { font-size: .9rem; }
.why-visual {
  background: var(--gray-50);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-xl);
  height: 340px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
}
.why-visual-inner { text-align: center; }
.why-visual-inner .emoji { font-size: 4rem; margin-bottom: 16px; display: block; }
.why-visual-inner p { font-size: .9rem; color: var(--gray-600); }

/* ─── Feature Cards (3-col) ─── */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 28px;
}
.feature-card {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  transition: var(--transition);
}
.feature-card:hover {
  border-color: var(--gray-400);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}
.feature-card .fc-icon {
  width: 52px;
  height: 52px;
  background: var(--black);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  margin-bottom: 20px;
}
.feature-card h3 { font-size: 1.15rem; margin-bottom: 10px; }
.feature-card p { font-size: .93rem; }

/* ─── Testimonials Carousel ─── */
.testimonials-section { background: var(--black); color: var(--white); }
.testimonials-section .section-label { background: rgba(230,255,50,.15); color: var(--lime); }
.testimonials-section .section-header h2 { color: var(--white); }
.testimonials-section .section-header p { color: rgba(255,255,255,.6); }
.carousel-wrapper { position: relative; overflow: hidden; }
.carousel-track {
  display: flex;
  gap: 24px;
  transition: transform .45s cubic-bezier(.4,0,.2,1);
}
.testimonial-card {
  flex: 0 0 calc(33.333% - 16px);
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: var(--radius-lg);
  padding: 32px 28px;
}
.testimonial-tag {
  display: inline-block;
  background: var(--lime);
  color: var(--black);
  font-size: .75rem;
  font-weight: 800;
  padding: 3px 10px;
  border-radius: 50px;
  margin-bottom: 14px;
}
.testimonial-card blockquote {
  font-size: 1rem;
  color: rgba(255,255,255,.85);
  line-height: 1.7;
  margin-bottom: 20px;
  font-style: italic;
}
.testimonial-author { display: flex; align-items: center; gap: 12px; }
.author-avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: var(--burgundy);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: .9rem;
  color: var(--lime);
  flex-shrink: 0;
}
.author-name { font-weight: 700; color: var(--white); font-size: .9rem; }
.author-title { font-size: .8rem; color: rgba(255,255,255,.5); }
.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 36px;
  align-items: center;
}
.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1.5px solid rgba(255,255,255,.2);
  background: rgba(255,255,255,.06);
  color: var(--white);
  cursor: pointer;
  font-size: 1rem;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel-btn:hover { background: var(--lime); color: var(--black); border-color: var(--lime); }
.carousel-dots { display: flex; gap: 8px; }
.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,.25);
  cursor: pointer;
  transition: var(--transition);
}
.carousel-dot.active { background: var(--lime); width: 24px; border-radius: 4px; }

/* ─── Pricing Overview ─── */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 20px;
  margin-bottom: 40px;
}
.pricing-card {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  transition: var(--transition);
  position: relative;
}
.pricing-card.featured {
  border-color: var(--black);
  background: var(--black);
  color: var(--white);
}
.pricing-card.featured p { color: rgba(255,255,255,.65); }
.pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--lime);
  color: var(--black);
  font-size: .72rem;
  font-weight: 800;
  padding: 4px 12px;
  border-radius: 50px;
  white-space: nowrap;
}
.pricing-name { font-weight: 800; font-size: 1rem; margin-bottom: 8px; font-family: var(--font-heading); }
.pricing-price {
  font-family: var(--font-heading);
  font-weight: 900;
  font-size: 2.2rem;
  letter-spacing: -0.03em;
  color: var(--black);
  line-height: 1;
  margin-bottom: 4px;
}
.pricing-card.featured .pricing-price { color: var(--lime); }
.pricing-period { font-size: .8rem; color: var(--gray-400); margin-bottom: 20px; }
.pricing-card.featured .pricing-period { color: rgba(255,255,255,.5); }
.pricing-features { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.pricing-features li {
  font-size: .875rem;
  color: var(--gray-600);
  display: flex;
  align-items: flex-start;
  gap: 8px;
  line-height: 1.4;
}
.pricing-features li::before {
  content: '✓';
  font-weight: 900;
  color: var(--burgundy);
  flex-shrink: 0;
}
.pricing-card.featured .pricing-features li { color: rgba(255,255,255,.7); }
.pricing-card.featured .pricing-features li::before { color: var(--lime); }

/* ─── Integrations ─── */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: 16px;
}
.integration-item {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 20px 16px;
  text-align: center;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}
.integration-item:hover {
  border-color: var(--black);
  box-shadow: var(--shadow-sm);
  transform: translateY(-2px);
}
.integration-logo {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  font-weight: 800;
}
.integration-item span {
  font-size: .78rem;
  font-weight: 700;
  color: var(--gray-700);
}

/* ─── FAQ Accordion ─── */
.faq-list { max-width: 760px; margin: 0 auto; display: flex; flex-direction: column; gap: 12px; }
.faq-item {
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: var(--transition);
}
.faq-item.open { border-color: var(--black); }
.faq-question {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 24px;
  cursor: pointer;
  font-weight: 700;
  font-size: 1rem;
  transition: var(--transition);
  background: var(--white);
  gap: 16px;
}
.faq-question:hover { background: var(--gray-50); }
.faq-item.open .faq-question { background: var(--black); color: var(--white); }
.faq-chevron {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .8rem;
  flex-shrink: 0;
  transition: transform var(--transition);
}
.faq-item.open .faq-chevron { background: var(--lime); transform: rotate(180deg); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height .35s ease;
}
.faq-answer-inner { padding: 0 24px 20px; color: var(--gray-600); font-size: .95rem; line-height: 1.7; }

/* ─── Global Scale ─── */
.global-section { background: var(--gray-50); }
.global-content { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
.global-map {
  background: var(--black);
  border-radius: var(--radius-xl);
  height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.global-map-dots { font-size: 5rem; opacity: .2; position: absolute; }
.global-map-stat {
  background: var(--lime);
  border-radius: var(--radius-md);
  padding: 20px 28px;
  text-align: center;
  position: relative;
  z-index: 1;
}
.global-map-stat .num { font-size: 2.5rem; font-weight: 900; color: var(--black); font-family: var(--font-heading); letter-spacing: -0.03em; }
.global-map-stat .lbl { font-size: .85rem; font-weight: 700; color: rgba(0,0,0,.6); }

/* ─── AI Automations ─── */
.ai-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
}
.ai-card {
  background: var(--black);
  border-radius: var(--radius-lg);
  padding: 32px 26px;
  color: var(--white);
  transition: var(--transition);
  border: 1px solid rgba(255,255,255,.06);
}
.ai-card:hover { border-color: var(--lime); transform: translateY(-3px); }
.ai-card .ai-icon {
  width: 48px;
  height: 48px;
  background: var(--lime);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.3rem;
  margin-bottom: 18px;
}
.ai-card h4 { color: var(--white); font-size: 1.05rem; margin-bottom: 8px; }
.ai-card p { color: rgba(255,255,255,.6); font-size: .9rem; }

/* ─── Social Proof Bar ─── */
.social-proof { background: var(--black); padding: 48px 0; }
.social-proof-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  flex-wrap: wrap;
}
.social-logos { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; }
.social-logo-pill {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 50px;
  padding: 8px 18px;
  font-size: .8rem;
  font-weight: 700;
  color: rgba(255,255,255,.6);
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ─── 3-Steps Section ─── */
.steps-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 32px; }
.step-card {
  position: relative;
  padding: 36px 28px;
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  transition: var(--transition);
}
.step-card:hover { border-color: var(--black); box-shadow: var(--shadow-md); transform: translateY(-3px); }
.step-num {
  font-family: var(--font-heading);
  font-size: 4rem;
  font-weight: 900;
  color: var(--lime);
  line-height: 1;
  margin-bottom: 16px;
  -webkit-text-stroke: 2px var(--gray-200);
  color: transparent;
  position: relative;
}
.step-num::after {
  content: attr(data-num);
  position: absolute;
  left: 0;
  top: 0;
  color: var(--lime);
  -webkit-text-stroke: 0;
}
.step-card h3 { font-size: 1.15rem; margin-bottom: 10px; }
.step-card p { font-size: .92rem; }

/* ─── Tools Grid ─── */
.tools-section { background: var(--gray-50); }
.tools-categories { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 24px; }
.tools-category {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 24px;
}
.tools-category-label {
  font-size: .75rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: var(--burgundy);
  margin-bottom: 14px;
}
.tool-tag {
  display: inline-block;
  background: var(--gray-100);
  color: var(--gray-700);
  padding: 5px 12px;
  border-radius: 50px;
  font-size: .8rem;
  font-weight: 600;
  margin: 3px 3px 0 0;
}

/* ─── CTA Banner ─── */
.cta-banner {
  background: var(--black);
  text-align: center;
  padding: 80px 0;
  position: relative;
  overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 70% 80% at 50% 50%, rgba(230,255,50,.1) 0%, transparent 70%);
}
.cta-banner .container { position: relative; }
.cta-banner h2 { color: var(--white); margin-bottom: 16px; max-width: 640px; margin: 0 auto 16px; }
.cta-banner p { color: rgba(255,255,255,.65); margin-bottom: 36px; font-size: 1.05rem; }
.cta-actions { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }

/* ─── Resources ─── */
.resources-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 24px; }
.resource-card {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: var(--transition);
}
.resource-card:hover { border-color: var(--black); box-shadow: var(--shadow-md); transform: translateY(-3px); }
.resource-img {
  height: 140px;
  background: linear-gradient(135deg, var(--black) 0%, #1a1a2e 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  position: relative;
}
.resource-img-label {
  position: absolute;
  top: 12px;
  left: 12px;
  background: var(--lime);
  color: var(--black);
  font-size: .7rem;
  font-weight: 800;
  padding: 3px 10px;
  border-radius: 50px;
}
.resource-body { padding: 24px; }
.resource-body h4 { font-size: 1rem; margin-bottom: 8px; }
.resource-body p { font-size: .88rem; }
.resource-link { display: inline-flex; align-items: center; gap: 6px; color: var(--black); font-weight: 700; font-size: .875rem; margin-top: 14px; }
.resource-link:hover { text-decoration: underline; }

/* ─── Membership Pricing ─── */
.membership-tiers { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 24px; }
.tier-card {
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  transition: var(--transition);
  background: var(--white);
  position: relative;
}
.tier-card:hover { border-color: var(--black); box-shadow: var(--shadow-md); }
.tier-card.highlight { border-color: var(--black); background: var(--black); }
.tier-card.highlight h3, .tier-card.highlight .tier-price { color: var(--white); }
.tier-card.highlight p { color: rgba(255,255,255,.55); }
.tier-name { font-size: .8rem; font-weight: 800; text-transform: uppercase; letter-spacing: .1em; color: var(--burgundy); margin-bottom: 8px; }
.tier-card.highlight .tier-name { color: var(--lime); }
.tier-price { font-family: var(--font-heading); font-size: 2.4rem; font-weight: 900; letter-spacing: -0.03em; color: var(--black); line-height: 1; }
.tier-period { font-size: .8rem; color: var(--gray-400); margin-bottom: 16px; }
.tier-card.highlight .tier-period { color: rgba(255,255,255,.4); }
.tier-features { list-style: none; display: flex; flex-direction: column; gap: 10px; margin-bottom: 28px; }
.tier-features li { font-size: .875rem; color: var(--gray-600); display: flex; gap: 8px; align-items: flex-start; }
.tier-features li::before { content: '✓'; color: var(--burgundy); font-weight: 900; flex-shrink: 0; }
.tier-card.highlight .tier-features li { color: rgba(255,255,255,.65); }
.tier-card.highlight .tier-features li::before { color: var(--lime); }

/* ─── Footer ─── */
.footer {
  background: var(--black);
  color: rgba(255,255,255,.65);
  padding: 64px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}
.footer-brand .nav-logo { margin-bottom: 14px; color: var(--white); }
.footer-brand p { font-size: .875rem; line-height: 1.7; max-width: 260px; }
.footer-col h5 {
  font-size: .875rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: .06em;
}
.footer-links { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-links a { font-size: .875rem; color: rgba(255,255,255,.55); transition: color var(--transition); }
.footer-links a:hover { color: var(--lime); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  font-size: .8rem;
}
.footer-bottom a { color: rgba(255,255,255,.45); transition: color var(--transition); }
.footer-bottom a:hover { color: var(--lime); }

/* ─── Value Prop Cards ─── */
.value-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 28px; }
.value-card {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  transition: var(--transition);
}
.value-card:hover { border-color: var(--black); box-shadow: var(--shadow-md); transform: translateY(-3px); }
.value-num {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 900;
  color: var(--lime);
  line-height: 1;
  margin-bottom: 16px;
  -webkit-text-stroke: 2px var(--gray-900);
}
.value-card h3 { font-size: 1.1rem; margin-bottom: 8px; }

/* ─── File Types Grid ─── */
.file-types-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 16px; }
.file-type-item {
  background: var(--gray-50);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 24px 16px;
  text-align: center;
  transition: var(--transition);
}
.file-type-item:hover { border-color: var(--black); background: var(--lime); }
.file-type-item:hover span { color: var(--black); }
.file-type-icon { font-size: 1.8rem; margin-bottom: 8px; }
.file-type-item span { font-size: .8rem; font-weight: 700; color: var(--gray-700); }

/* ─── Coaching Spotlight ─── */
.spotlight-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 24px; }
.spotlight-card {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: var(--transition);
}
.spotlight-card:hover { border-color: var(--black); box-shadow: var(--shadow-md); transform: translateY(-3px); }
.spotlight-header {
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2.5rem;
  position: relative;
}
.spotlight-body { padding: 24px; }
.spotlight-body h3 { font-size: 1.1rem; margin-bottom: 8px; }
.spotlight-body p { font-size: .9rem; }

/* ─── Hero Variants ─── */
.hero-split {
  background: var(--black);
  color: var(--white);
  padding: 100px 0 80px;
  position: relative;
  overflow: hidden;
}
.hero-split::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 60% 80% at 80% 50%, rgba(230,255,50,.1) 0%, transparent 60%);
}
.hero-split .container { position: relative; z-index: 1; display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
.hero-split h1 { color: var(--white); margin-bottom: 20px; }
.hero-split p { color: rgba(255,255,255,.72); font-size: 1.1rem; margin-bottom: 36px; }
.hero-illustration {
  background: rgba(255,255,255,.06);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-xl);
  height: 360px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
}
.hero-float-card {
  background: rgba(255,255,255,.1);
  border: 1px solid rgba(255,255,255,.15);
  border-radius: var(--radius-md);
  padding: 16px 20px;
  color: var(--white);
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 14px;
}
.float-icon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  background: var(--lime);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  flex-shrink: 0;
  color: var(--black);
}
.float-text h5 { font-size: .9rem; color: var(--white); }
.float-text p { font-size: .78rem; color: rgba(255,255,255,.55); margin: 0; }

/* ─── Membership Stats ─── */
.membership-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 28px; }
.membership-stat-card {
  background: var(--black);
  border-radius: var(--radius-lg);
  padding: 36px 28px;
  text-align: center;
  color: var(--white);
}
.membership-stat-num {
  font-family: var(--font-heading);
  font-size: 2.8rem;
  font-weight: 900;
  color: var(--lime);
  letter-spacing: -0.03em;
  margin-bottom: 8px;
}
.membership-stat-card h4 { color: var(--white); font-size: 1rem; margin-bottom: 10px; }
.membership-stat-card p { color: rgba(255,255,255,.55); font-size: .875rem; }

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
  .footer-brand { grid-column: span 3; }
  .hero-split .container { grid-template-columns: 1fr; }
  .hero-illustration { display: none; }
  .global-content { grid-template-columns: 1fr; }
  .why-panel.active { grid-template-columns: 1fr; }
}
@media (max-width: 768px) {
  .section { padding: 64px 0; }
  .nav-links, .nav-cta { display: none; }
  .nav-toggle { display: flex; }
  .nav-links.open {
    display: flex;
    flex-direction: column;
    position: fixed;
    top: 68px;
    left: 0;
    right: 0;
    background: var(--white);
    border-bottom: 1px solid var(--gray-200);
    padding: 16px 24px;
    box-shadow: var(--shadow-md);
    z-index: 99;
  }
  .nav-cta.open { display: flex; padding: 0 24px 16px; position: fixed; top: auto; bottom: 0; left: 0; right: 0; z-index: 99; background: var(--white); border-top: 1px solid var(--gray-200); box-shadow: var(--shadow-md); padding: 16px 24px; }
  .testimonial-card { flex: 0 0 calc(100% - 0px); }
  .stats-bar .container { gap: 32px; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-brand { grid-column: span 2; }
  .hero-preview { display: none !important; }
  .pricing-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-brand { grid-column: span 1; }
  .pricing-grid { grid-template-columns: 1fr; }
}

raw_arguments.content:
/* LearnForge Global Styles */
:root {
  --black: #000000;
  --lime: #E6FF32;
  --burgundy: #7F2A23;
  --white: #ffffff;
  --gray-50: #f9fafb;
  --gray-100: #f3f4f6;
  --gray-200: #e5e7eb;
  --gray-400: #9ca3af;
  --gray-600: #4b5563;
  --gray-700: #374151;
  --gray-900: #111827;
  --font-heading: 'Plus Jakarta Sans', 'Inter', sans-serif;
  --font-body: 'Inter', sans-serif;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.06);
  --shadow-md: 0 4px 16px rgba(0,0,0,.10);
  --shadow-lg: 0 12px 40px rgba(0,0,0,.12);
  --transition: .22s cubic-bezier(.4,0,.2,1);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--gray-900);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }
a { text-decoration: none; color: inherit; }

/* ─── Typography ─── */
h1, h2, h3, h4, h5 {
  font-family: var(--font-heading);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.02em;
}
h1 { font-size: clamp(2.4rem, 5vw, 4rem); }
h2 { font-size: clamp(1.8rem, 3.5vw, 2.8rem); }
h3 { font-size: clamp(1.3rem, 2.5vw, 1.8rem); }
h4 { font-size: 1.15rem; font-weight: 700; }
p  { color: var(--gray-600); line-height: 1.7; }

/* ─── Layout ─── */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}
.section { padding: 96px 0; }
.section-sm { padding: 64px 0; }

/* ─── Buttons ─── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: .95rem;
  padding: 14px 28px;
  border-radius: 50px;
  cursor: pointer;
  transition: var(--transition);
  border: 2px solid transparent;
  white-space: nowrap;
}
.btn-primary {
  background: var(--black);
  color: var(--lime);
  border-color: var(--black);
}
.btn-primary:hover {
  background: var(--gray-900);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0,0,0,.25);
}
.btn-outline {
  background: transparent;
  color: var(--black);
  border-color: var(--black);
}
.btn-outline:hover {
  background: var(--black);
  color: var(--lime);
  transform: translateY(-2px);
}
.btn-lime {
  background: var(--lime);
  color: var(--black);
  border-color: var(--lime);
}
.btn-lime:hover {
  background: #d4eb1a;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(230,255,50,.35);
}
.btn-sm { padding: 10px 20px; font-size: .875rem; }

/* ─── Nav ─── */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}
.nav.scrolled { box-shadow: var(--shadow-md); }
.nav-inner {
  display: flex;
  align-items: center;
  gap: 32px;
  height: 68px;
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 900;
  color: var(--black);
  letter-spacing: -0.04em;
  margin-right: auto;
  display: flex;
  align-items: center;
  gap: 6px;
}
.nav-logo span {
  display: inline-block;
  width: 28px;
  height: 28px;
  background: var(--lime);
  border-radius: 6px;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
}
.nav-links a {
  font-size: .9rem;
  font-weight: 600;
  color: var(--gray-700);
  padding: 8px 14px;
  border-radius: 8px;
  transition: var(--transition);
}
.nav-links a:hover, .nav-links a.active {
  color: var(--black);
  background: var(--gray-100);
}
.nav-cta { margin-left: 8px; }

/* Mobile nav toggle */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 4px;
  background: none;
  border: none;
}
.nav-toggle span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--black);
  border-radius: 2px;
  transition: var(--transition);
}

/* ─── Hero ─── */
.hero {
  background: var(--black);
  color: var(--white);
  padding: 80px 0 0;
  overflow: hidden;
  position: relative;
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 80% 60% at 70% 50%, rgba(230,255,50,.12) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content { position: relative; z-index: 1; text-align: center; max-width: 800px; margin: 0 auto 56px; }
.hero h1 { color: var(--white); margin-bottom: 20px; }
.hero h1 em { color: var(--lime); font-style: normal; }
.hero p { color: rgba(255,255,255,.72); font-size: 1.15rem; max-width: 600px; margin: 0 auto 36px; }
.hero-actions { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }

/* Tab switcher */
.hero-tabs {
  display: inline-flex;
  background: rgba(255,255,255,.1);
  border-radius: 50px;
  padding: 4px;
  gap: 0;
  margin-bottom: 48px;
}
.hero-tab {
  padding: 10px 24px;
  border-radius: 50px;
  font-size: .9rem;
  font-weight: 700;
